import docx

d = docx.Document('/home/lladlam/下载/2026 首届 openvela AI 硬件开发者大赛 - 作品提交模板.docx')
def st(p):
    return getattr(p.style, 'name', 'None') if p.style else 'None'

print('=== PARAGRAPHS ===')
for i, p in enumerate(d.paragraphs):
    t = p.text.strip()
    if t:
        print(f'[{i}] {st(p):20s} | {t[:120]}')
print()
print('=== TABLES ===')
for ti, t in enumerate(d.tables):
    print(f'Table {ti}: {len(t.rows)} rows x {len(t.columns)} cols')
    for ri, row in enumerate(t.rows):
        cells = [c.text.strip()[:50] for c in row.cells]
        print(f'  row{ri}: {cells}')
print()
print('=== STYLES USED ===')
styles = set()
for p in d.paragraphs:
    styles.add(st(p))
for t in d.tables:
    for row in t.rows:
        for c in row.cells:
            for p in c.paragraphs:
                styles.add(st(p))
print(sorted(styles))
